mapper.select:
select p.id , p.slug , p.title , p.summary , p.view_count , p.published_at , p.thumbnail_key , p.thumbnail_metadata , p.comment_count , t.name as tag_name from ( select a.id , a.slug , a.title , a.summary , a.view_count , a.published_at , c.key as thumbnail_key , c.metadata as thumbnail_metadata , (select count(*) from comments where post_id = a.id and deleted_at is null) as comment_count from posts a left join attachments b on b.record_id = text(a.id) and b.record_type = 'post' and b.name = 'thumbnail' left join blobs c on c.id = b.blob_id where a.post_type = #{postType}
order by a.view_count ${sortDir}, a.published_at desc
order by a.published_at ${sortDir}
order by a.published_at desc
limit #{limit} offset #{offset} ) p left join post_tags pt on pt.post_id = p.id left join tags t on t.id = pt.tag_id
order by p.view_count ${sortDir}, p.published_at desc
order by p.published_at ${sortDir}
order by p.published_at desc

select count(*)
from posts
where post_type = #{postType}
